                    dr = abs(r - sr)
                    if dr % 2 == 0:
                        # Even distance: paint at same column
                        result[r][sc] = seed_val
                    else:
                        # Odd distance: paint at adjacent columns
                        if sc > 0:
                            result[r][sc - 1] = seed_val
                        if sc < cols - 1:
                            result[r][sc + 1] = seed_val

    return result
